<dialog class="lead" id="lead" aria-labelledby="lead-title">
  <div class="lead-in">
    <button class="lead-x" type="button" data-lead-close data-i18n-aria="lead.close" aria-label="Close"><svg class="ic" aria-hidden="true"><use href="#i-x"/></svg></button>
    <div data-lead-step="form">
      <p class="lead-plan" data-lead-plan>Fandaqah 360 upgrade</p>
      <h2 id="lead-title" data-i18n="lead.title">Reserve your launch pricing</h2>
      <p class="lead-sub" data-i18n="lead.sub">Leave your details. Our team will contact you shortly to confirm your offer and reserve the launch price, with the option of a second year at the same rate.</p>
      <form class="lead-form" novalidate>
        <div class="field">
          <label for="lead-name" data-i18n="lead.name">Full name</label>
          <input id="lead-name" name="name" type="text" autocomplete="name" maxlength="80" required aria-describedby="lead-name-err">
          <p class="err" id="lead-name-err" data-i18n="lead.nameErr" hidden>Please enter your name.</p>
        </div>
        <div class="field">
          <label for="lead-email" data-i18n="lead.email">Email</label>
          <input id="lead-email" name="email" type="email" autocomplete="email" maxlength="120" dir="ltr" required aria-describedby="lead-email-err">
          <p class="err" id="lead-email-err" data-i18n="lead.emailErr" hidden>Please enter a valid email address.</p>
        </div>
        <div class="field">
          <label for="lead-phone" data-i18n="lead.phone">Mobile number (Saudi Arabia)</label>
          <div class="tel" dir="ltr"><span class="tel-cc" aria-hidden="true">+966</span><input id="lead-phone" name="phone" type="tel" inputmode="numeric" autocomplete="tel-national" placeholder="5X XXX XXXX" maxlength="20" required aria-describedby="lead-phone-err"></div>
          <p class="err" id="lead-phone-err" data-i18n="lead.phoneErr" hidden>Enter a Saudi mobile number: 9 digits starting with 5.</p>
        </div>
        <div class="field">
          <label for="lead-msg"><span data-i18n="lead.msg">Message</span> <span class="opt" data-i18n="lead.opt">(optional)</span></label>
          <textarea id="lead-msg" name="message" rows="3" maxlength="1000"></textarea>
        </div>
        <div class="hp" aria-hidden="true"><label>Website <input name="website" type="text" tabindex="-1" autocomplete="off"></label></div>
        <p class="lead-alert" role="alert" hidden></p>
        <button class="btn btn-coral lead-submit" type="submit"><span data-i18n="lead.send">Send request</span></button>
        <p class="assure lead-assure" data-lead-guar><svg class="tok" aria-hidden="true"><use href="#i-seal"/></svg><span data-i18n="lead.guar">Covered by our 30-day golden guarantee.</span></p>
        <p class="lead-note" data-i18n="lead.note">We only use your details to contact you about Fandaqah.</p>
      </form>
    </div>
    <div class="lead-done" data-lead-step="done" hidden>
      <span class="tick-lg" aria-hidden="true"><svg class="ic"><use href="#i-check"/></svg></span>
      <h2 tabindex="-1" data-i18n="lead.doneT">Thank you!</h2>
      <p class="lead-sub" data-i18n="lead.doneD">We’ve received your request. Our team will contact you shortly.</p>
      <button class="btn btn-navy" type="button" data-lead-close data-i18n="lead.closeBtn">Close</button>
    </div>
  </div>
</dialog>

