      const r = RATE[p.dataset.plane];
      const y = cy * r.y + cyp * r.px * .6, x = cx * r.px;
      p.style.transform = `translate3d(${x.toFixed(2)}px, ${y.toFixed(2)}px, 0)` + (r.s ? ` scale(${(1 + cy * r.s).toFixed(4)})` : '');
    });
    if (Math.abs(sy - cy) > .1 || Math.abs(tx - cx) > .002 || Math.abs(ty - cyp) > .002) requestAnimationFrame(frame);
    else running = false;
  }
  const kick = () => { if (!running) { running = true; requestAnimationFrame(frame); } };
  const depthOn = () => wide.matches && !reduce.matches;
  addEventListener('scroll', () => {
    if (!depthOn()) return;
    const y = scrollY;
    if (y > hero.offsetHeight + 200 && cy > hero.offsetHeight) return;
    sy = Math.min(y, hero.offsetHeight + 200); kick();
  }, { passive: true });
  hero.addEventListener('pointermove', e => {
    if (!depthOn() || !fine.matches || e.pointerType !== 'mouse') return;
    tx = (e.clientX / innerWidth - .5) * 2; ty = (e.clientY / innerHeight - .5) * 2; kick();
  });
  hero.addEventListener('pointerleave', () => { tx = 0; ty = 0; kick(); });
  const resetDepth = () => { if (!depthOn()) { sy = cy = tx = ty = cx = cyp = 0; planes.forEach(p => { p.style.transform = ''; }); } };
  wide.addEventListener('change', resetDepth); reduce.addEventListener('change', resetDepth);
})();
</script>
